 import type {ButtonId} from './actions';
 let {speed,pitch,keymap,disabled=false,controls,runButton}:{speed:number;pitch:number;disabled?:boolean;keymap:Keymap;controls:(speed:number,pitch:number)=>void;runButton:(id:ButtonId,payload?:{speed?:number})=>void}=$props();
</script>
