 <section aria-label="Playback speed"><label for="speed-percent">Speed</label><div class="number"><input id="speed-percent" {disabled} aria-label="Speed percent" type="number" min="25" max="200" step="1" value={Math.round(speed*100)} onchange={event=>controls(Number(event.currentTarget.value)/100,pitch)}/><span>%</span></div><input {disabled} aria-label="Playback speed" type="range" min="25" max="200" step="1" value={speed*100} oninput={event=>controls(Number(event.currentTarget.value)/100,pitch)}/><div class="presets">{#each [.5,.75,1] as preset}<button {disabled} class:chosen={Math.abs(speed-preset)<.005} title={keymap.title('speed_preset')} onclick={()=>runButton('speed_preset',{speed:preset})}>{preset*100}%</button>{/each}</div><button {disabled} class="icon-button" aria-label="Reset speed" title={keymap.title('reset_speed')} onclick={()=>runButton('reset_speed')}><Icon name="reset" size={15}/></button></section>
